import json,zipfile,hashlib
from pathlib import Path
import numpy as np,pandas as pd
from sklearn.cluster import KMeans
from sklearn.metrics import adjusted_rand_score,silhouette_score
P=Path(__file__).resolve().parent;z=zipfile.ZipFile(P/'data/snapshot.zip');d=pd.read_csv(z.open(z.namelist()[0]),sep=';',dtype={'GEO':str,'FACILITY_TYPE':str});d=d[(d.TIME_PERIOD==2025)&(d.GEO_OBJECT=='COM')];d.loc[d.OBS_STATUS!='A','OBS_VALUE']=np.nan;x=d.pivot(index='GEO',columns='FACILITY_TYPE',values='OBS_VALUE');x=(x==1).astype(int);x=x.loc[x.sum(axis=1)>0];x=x.loc[:,x.sum(axis=0)>0];assert np.isin(x.to_numpy(),[0,1]).all();m=KMeans(n_clusters=6,n_init=10,random_state=42).fit(x);other=KMeans(n_clusters=6,n_init=10,random_state=7).fit_predict(x);baseline=pd.qcut(x.sum(axis=1).rank(method='first'),6,labels=False);centers=pd.DataFrame(m.cluster_centers_,columns=x.columns);centers.to_csv(P/'centres.csv',index_label='groupe');x.to_csv(P/'data/presence.csv');result={'communes':len(x),'types':x.shape[1],'cluster_counts':{str(i):int((m.labels_==i).sum()) for i in range(6)},'ari_graines':float(adjusted_rand_score(m.labels_,other)),'silhouette':float(silhouette_score(x,m.labels_,sample_size=2000,random_state=42)),'silhouette_quantiles_nombre':float(silhouette_score(x,baseline,sample_size=2000,random_state=42)),'nombre_types_moyen_groupe':{str(i):float(x.sum(axis=1)[m.labels_==i].mean()) for i in range(6)},'snapshot_sha256':hashlib.sha256((P/'data/snapshot.zip').read_bytes()).hexdigest()};(P/'results.json').write_text(json.dumps(result,indent=2));print(json.dumps(result,indent=2))
